	t.Helper()
	a, err := newAgent(context.Background(), &server{endpoint: "http://127.0.0.1:1", stateDir: stateDir}, NewControls(), "")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _ = a.layer.Close(context.Background()) })
	return a
