			t.Fatalf("a state dir it can't save in: the resource's UUID, got %s", u)
		}
	}
	if u := identity(unsaved, "", time.Now()); u.Version() != 7 {
		t.Fatalf("a state dir it can't save in, nothing given: a new UUIDv7, got %s", u)
